<?php $statusLabels = ['draft' => 'Borrador', 'sent' => 'Enviada', 'accepted' => 'Aceptada', 'rejected' => 'Rechazada']; ?>
<div class="admin-page-heading"><div><span class="admin-eyebrow">Cotización <?= e($quote['quote_number']) ?></span><h1><?= e($quote['company']) ?></h1><p><?= e($quote['subject']) ?></p></div><div class="admin-heading-actions"><a class="btn admin-secondary-btn" href="<?= url('/admin/cotizaciones') ?>">Volver</a><?php if (\App\Core\Auth::can('quotes.edit') && !in_array($quote['status'], ['accepted','rejected'], true)): ?><a class="btn admin-secondary-btn" href="<?= url('/admin/cotizaciones/editar?id=' . (int) $quote['id']) ?>">Editar</a><?php endif; ?><a class="btn admin-primary-btn" target="_blank" href="<?= url('/admin/cotizaciones/pdf?id=' . (int) $quote['id']) ?>">Ver PDF</a></div></div>
<div class="row g-4"><div class="col-xl-8"><section class="admin-panel quote-preview"><div class="quote-preview__header"><div><span>Propuesta comercial</span><strong><?= e($quote['quote_number']) ?></strong></div><span class="status-badge status-<?= e($quote['status']) ?>"><?= e($statusLabels[$quote['status']] ?? '') ?></span></div><div class="quote-preview__client"><div><span>Cliente</span><strong><?= e($quote['company']) ?></strong><p><?= e($quote['client_name']) ?> · <?= e($quote['email']) ?></p></div><div><span>Emisión</span><strong><?= e(date('d/m/Y', strtotime($quote['issue_date']))) ?></strong></div><div><span>Válida hasta</span><strong><?= e(date('d/m/Y', strtotime($quote['valid_until']))) ?></strong></div></div><div class="table-responsive"><table class="table admin-table quote-lines mb-0"><thead><tr><th>Servicio</th><th class="text-end">Cantidad</th><th class="text-end">Valor</th><th class="text-end">Total</th></tr></thead><tbody><?php foreach ($quote['items'] as $item): ?><tr><td><strong><?= e($item['description']) ?></strong><?php if ($item['detail']): ?><small><?= e($item['detail']) ?></small><?php endif; ?></td><td class="text-end"><?= e(rtrim(rtrim(number_format((float) $item['quantity'], 2, ',', '.'), '0'), ',')) ?></td><td class="text-end"><?= money_clp($item['unit_price']) ?></td><td class="text-end"><strong><?= money_clp($item['total']) ?></strong></td></tr><?php endforeach; ?></tbody></table></div><div class="quote-preview__bottom"><div><?php if ($quote['notes']): ?><span>Observaciones</span><p><?= nl2br(e($quote['notes'])) ?></p><?php endif; ?><?php if ($quote['terms']): ?><span>Condiciones</span><p><?= nl2br(e($quote['terms'])) ?></p><?php endif; ?></div><dl><div><dt>Subtotal</dt><dd><?= money_clp($quote['subtotal']) ?></dd></div><div><dt>IVA <?= e(rtrim(rtrim(number_format((float) $quote['tax_rate'], 2, ',', '.'), '0'), ',')) ?>%</dt><dd><?= money_clp($quote['tax_amount']) ?></dd></div><div><dt>Total</dt><dd><?= money_clp($quote['total']) ?></dd></div></dl></div></section></div>
<div class="col-xl-4"><section class="admin-panel admin-side-card"><h2>Envío y respuesta</h2><p class="admin-meta">Destino: <strong><?= e($quote['email']) ?></strong></p><?php if (\App\Core\Auth::can('quotes.send') && !in_array($quote['status'], ['accepted','rejected'], true)): ?><form method="post" action="<?= url('/admin/cotizaciones/enviar') ?>" onsubmit="return confirm('¿Enviar esta cotización al correo indicado?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $quote['id'] ?>"><button class="btn admin-primary-btn w-100" type="submit"><?= $quote['status'] === 'sent' ? 'Reenviar cotización' : 'Enviar por correo' ?></button></form><?php endif; ?><a class="btn admin-secondary-btn w-100 mt-2" target="_blank" href="<?= url('/cotizacion?token=' . e($quote['public_token'])) ?>">Abrir vista del cliente</a><?php if ($quote['status'] === 'accepted'): ?><div class="quote-result quote-result--accepted"><strong>Aceptada</strong><span><?= e(date('d/m/Y H:i', strtotime($quote['accepted_at']))) ?></span></div><?php elseif ($quote['status'] === 'rejected'): ?><div class="quote-result quote-result--rejected"><strong>Rechazada</strong><span><?= e(date('d/m/Y H:i', strtotime($quote['rejected_at']))) ?></span><?php if ($quote['rejection_reason']): ?><p><?= e($quote['rejection_reason']) ?></p><?php endif; ?></div><?php elseif ($quote['sent_at']): ?><p class="admin-meta">Último envío: <?= e(date('d/m/Y H:i', strtotime($quote['sent_at']))) ?></p><?php endif; ?></section>
<section class="admin-panel admin-side-card mt-4"><h2>Historial</h2><div class="mini-timeline"><?php foreach ($quote['events'] as $event): ?><article><span></span><div><strong><?= e(ucfirst(str_replace('_', ' ', $event['event_type']))) ?></strong><small><?= e(date('d/m/Y H:i', strtotime($event['created_at']))) ?></small><p><?= e($event['details'] ?: '') ?></p></div></article><?php endforeach; ?></div></section>
<?php if (\App\Core\Auth::can('quotes.delete') && !in_array($quote['status'], ['accepted','rejected'], true)): ?><form class="mt-4" method="post" action="<?= url('/admin/cotizaciones/eliminar') ?>" onsubmit="return confirm('¿Eliminar esta cotización de forma permanente?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $quote['id'] ?>"><button class="btn admin-danger-btn w-100" type="submit">Eliminar cotización</button></form><?php endif; ?></div></div>
